mapper.select:
SELECT m.certificate_id AS certificateId, m.name AS name, COUNT(DISTINCT e.user_id) AS employeeCount FROM certificate m LEFT JOIN employee_certificate ee ON ee.certificate_id = m.certificate_id AND ee.company_id = #{companyId} LEFT JOIN employee e ON e.user_id = ee.user_id AND e.company_id = #{companyId} AND e.is_system = 0 AND e.deleted_at IS NULL AND e.resigned_at IS NULL WHERE m.company_id = #{companyId}
AND m.name LIKE CONCAT('%', #{keyword}, '%')
GROUP BY m.certificate_id, m.name ORDER BY m.name

SELECT COUNT(DISTINCT e.user_id)
  FROM employee_certificate ee
  JOIN employee e ON e.user_id = ee.user_id AND e.company_id = #{companyId}
       AND e.is_system = 0 AND e.deleted_at IS NULL AND e.resigned_at IS NULL
 WHERE ee.certificate_id = #{certificateId} AND ee.company_id = #{companyId}
